import RAPIER from '@dimforge/rapier3d-deterministic-compat';

export const EXPECTED_RAPIER_VERSION = '0.19.3' as const;
export const RAPIER_INIT_DIAGNOSTIC = Object.freeze({
  code: 'RAPIER_COMPAT_INIT_DEPRECATION_WARNING' as const,
  upstreamMessage: 'using deprecated parameters for the initialization function; pass a single object instead',
  handling: 'exposed_by_upstream_not_suppressed' as const,
});

export interface RapierRuntime {
  readonly module: typeof RAPIER;
  readonly version: typeof EXPECTED_RAPIER_VERSION;
  readonly initializationDiagnostic: typeof RAPIER_INIT_DIAGNOSTIC;
}

let initialization: Promise<RapierRuntime> | null = null;

/** Initialize WASM before a simulation tick. The exact upstream warning remains visible. */
export function initializeRapierRuntime(): Promise<RapierRuntime> {
  if (initialization) return initialization;
  initialization = (async () => {
    await RAPIER.init();
    const version = RAPIER.version();
    if (version !== EXPECTED_RAPIER_VERSION) {
      throw new Error(`PHYSICS_RAPIER_VERSION_MISMATCH expected ${EXPECTED_RAPIER_VERSION}, received ${version}`);
    }
    return Object.freeze({
      module: RAPIER,
      version,
      initializationDiagnostic: RAPIER_INIT_DIAGNOSTIC,
    });
  })().catch((error: unknown) => {
    initialization = null;
    throw error;
  });
  return initialization;
}

