// This module is internal to the strict tape loader, but the literal graph is
// still recursively frozen here so a direct module import cannot mutate the
// canonical source before the loader detaches it.
function deepFreezeRecorded<T>(value: T): Readonly<T> {
  if (value === null || typeof value !== 'object' || Object.isFrozen(value)) {
    return value;
  }
  for (const key of Reflect.ownKeys(value)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor && 'value' in descriptor) deepFreezeRecorded(descriptor.value);
  }
  return Object.freeze(value);
}

